// Generated by npm run prepare:supabase. Edit the original Joy payroll source instead.
export const ACCESS_MODULES = [
  { id: "dashboard", label: "Overview Dashboard", description: "Payroll totals, exceptions, and activity summary" },
  { id: "payroll", label: "Payroll Run", description: "Monthly salary calculations and payroll processing" },
  { id: "attendance", label: "Attendance", description: "Daily attendance, shift, week off, overtime, and remarks" },
  { id: "employees", label: "Employees", description: "Employee master, statutory, bank, and assignment details" },
  { id: "accommodation", label: "Accommodation", description: "Rooms, hostel recoveries, deductions, and return amounts" },
  { id: "payments", label: "Payments & Payslips", description: "Bank/cash outputs, payslips, and payment exports" },
  { id: "clients", label: "Clients & Employers", description: "Clients, employers, factory units, and status controls" },
  { id: "masters", label: "Operational Masters", description: "Accommodation types, shift timings, and reusable operational remarks" },
  { id: "operations", label: "Vehicle Monitoring", description: "Company vehicles, movements, fuel, expenses, and government/service reminders" },
  { id: "settings", label: "Rules & Settings", description: "Salary, statutory, overtime, attendance, and approval rules" },
  { id: "users", label: "Users & Access", description: "User profiles, roles, status, and permission customization" },
] as const;

export type AccessModule = (typeof ACCESS_MODULES)[number]["id"];
export type AccessLevel = "none" | "view" | "manage";
export type UserRole = "super_admin" | "payroll_team" | "hr_team" | "field_hr" | "hostel_incharge";
export type PermissionMap = Record<AccessModule, AccessLevel>;

export const ROLE_LABELS: Record<UserRole, string> = {
  super_admin: "Super Admin",
  payroll_team: "Payroll HR",
  hr_team: "HR Manager",
  field_hr: "Field HR",
  hostel_incharge: "Hostel In-charge",
};

const allManage = Object.fromEntries(ACCESS_MODULES.map((module) => [module.id, "manage"])) as PermissionMap;

export const DEFAULT_PERMISSIONS: Record<UserRole, PermissionMap> = {
  super_admin: allManage,
  payroll_team: {
    dashboard: "view",
    payroll: "manage",
    attendance: "view",
    employees: "view",
    accommodation: "manage",
    payments: "manage",
    clients: "view",
    masters: "view",
    operations: "view",
    settings: "view",
    users: "none",
  },
  hr_team: {
    dashboard: "view",
    payroll: "view",
    attendance: "manage",
    employees: "manage",
    accommodation: "manage",
    payments: "none",
    clients: "view",
    masters: "manage",
    operations: "manage",
    settings: "none",
    users: "none",
  },
  field_hr: {
    dashboard: "view", payroll: "view", attendance: "manage", employees: "manage", accommodation: "manage",
    payments: "none", clients: "view", masters: "view", operations: "view", settings: "none", users: "none",
  },
  hostel_incharge: { dashboard: "view", payroll: "none", attendance: "manage", employees: "view", accommodation: "manage", payments: "none", clients: "view", masters: "view", operations: "none", settings: "none", users: "none" },
};

export const DEFAULT_APPROVAL_ACCESS: Record<UserRole, boolean> = {
  super_admin: true,
  payroll_team: false,
  hr_team: false,
  field_hr: false,
  hostel_incharge: false,
};

export function normalizeRole(value: unknown): UserRole {
  return value === "super_admin" || value === "payroll_team" || value === "hr_team" || value === "field_hr" || value === "hostel_incharge" ? value : "field_hr";
}

export function normalizePermissions(role: UserRole, value: unknown): PermissionMap {
  if (role === "super_admin") return { ...DEFAULT_PERMISSIONS.super_admin };
  const input = value && typeof value === "object" ? value as Record<string, unknown> : {};
  return Object.fromEntries(ACCESS_MODULES.map((module) => {
    const requested = input[module.id];
    return [module.id, requested === "manage" || requested === "view" || requested === "none" ? requested : DEFAULT_PERMISSIONS[role][module.id]];
  })) as PermissionMap;
}

export function canView(permissions: PermissionMap, module: AccessModule) {
  return permissions[module] === "view" || permissions[module] === "manage";
}

export function canManage(permissions: PermissionMap, module: AccessModule) {
  return permissions[module] === "manage";
}
